-- Drop index "refunds_reversing" from table: "refunds"
DROP INDEX "payment"."refunds_reversing";
-- Modify "refunds" table
ALTER TABLE "payment"."refunds" DROP CONSTRAINT "refunds_reversed_check", DROP CONSTRAINT "refunds_reversing_check", DROP CONSTRAINT "refunds_external_state_check", ADD CONSTRAINT "refunds_external_state_check" CHECK ((external_refund_id IS NULL) OR (status = ANY (ARRAY['REFUNDING'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'ANOMALY'::text]))), DROP CONSTRAINT "refunds_status_check", ADD CONSTRAINT "refunds_status_check" CHECK (status = ANY (ARRAY['PENDING'::text, 'REFUNDING'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'ANOMALY'::text])), ADD CONSTRAINT "refunds_failed_releases_waiting_check" CHECK ((status <> 'FAILED'::text) OR (reversal_status <> 'WAITING'::text)), ADD CONSTRAINT "refunds_refund_lookup_failures_check" CHECK (refund_lookup_failures >= 0), ADD CONSTRAINT "refunds_reversal_after_acceptance_check" CHECK ((reversal_status <> ALL (ARRAY['REVERSING'::text, 'REVERSED'::text])) OR (external_refund_id IS NOT NULL)), ADD CONSTRAINT "refunds_reversal_external_check" CHECK ((reversal_status = 'REVERSED'::text) = (reversal_external_id IS NOT NULL)), ADD CONSTRAINT "refunds_reversal_none_check" CHECK ((reversal_status = 'NONE'::text) = (reversal_amount = 0)), ADD CONSTRAINT "refunds_reversal_reason_check" CHECK (((reversal_status = ANY (ARRAY['RELEASED'::text, 'ANOMALY'::text])) = (reversal_reason IS NOT NULL)) AND ((reversal_reason IS NULL) OR ((char_length(reversal_reason) >= 1) AND (char_length(reversal_reason) <= 200)))), ADD CONSTRAINT "refunds_reversal_status_check" CHECK (reversal_status = ANY (ARRAY['NONE'::text, 'WAITING'::text, 'REVERSING'::text, 'REVERSED'::text, 'RELEASED'::text, 'ANOMALY'::text])), ADD COLUMN "reversal_status" text NOT NULL DEFAULT 'NONE', ADD COLUMN "reversal_reason" text NULL, ADD COLUMN "refund_lookup_failures" integer NOT NULL DEFAULT 0;
-- Create index "refunds_reversing" to table: "refunds"
CREATE INDEX "refunds_reversing" ON "payment"."refunds" ("updated_at", "id") WHERE (reversal_status = 'REVERSING'::text);
-- Create index "refunds_open" to table: "refunds"
CREATE INDEX "refunds_open" ON "payment"."refunds" ("updated_at", "id") WHERE (status = ANY (ARRAY['PENDING'::text, 'REFUNDING'::text]));
